  // ── Portal: Get lab history ────────────────────────────────────────────────
  app.get("/api/portal/labs", requirePortalAuth, async (req, res) => {
    try {
      const patientId = (req.session as any).portalPatientId as number;
      logPhiAccess({ actorType: "patient_portal", actorId: patientId, action: "portal_view_labs", patientId, ipAddress: ipFromReq(req), userAgent: uaFromReq(req) });
      const labs = await storage.getLabResultsByPatient(patientId);
      // Load all protocols for this patient so we can attach clinicianNotes + dietaryGuidance per lab
      const protocols = await storage.getAllPublishedProtocols(patientId);
      const notesByLabId = new Map<number, string | null>();
      const dietaryByLabId = new Map<number, string | null>();
      for (const p of protocols) {
        if (p.labResultId) {
          if (p.clinicianNotes) notesByLabId.set(p.labResultId, p.clinicianNotes);
          // Use the most-recently-published dietary guidance per lab (protocols are desc by publishedAt)
          if (p.dietaryGuidance && !dietaryByLabId.has(p.labResultId)) {
            dietaryByLabId.set(p.labResultId, p.dietaryGuidance);
          }
        }
      }

      // Categories that belong in the hormone assessment section, not the lab values table
      const HORMONE_PATTERN_PREFIXES = ['Testosterone Pattern', 'Perimenopause Assessment:', 'Hormone Pattern:'];
      const isHormonePattern = (cat: string) => HORMONE_PATTERN_PREFIXES.some(p => cat.startsWith(p));

      // Return labs with patient-safe fields (no raw clinical scoring text)
      // Build per-lab maps for all published-protocol fields
      const summaryByLabId = new Map<number, string | null>();
      for (const p of protocols) {
        if (p.labResultId) {
          if (p.patientSummary && !summaryByLabId.has(p.labResultId)) {
            summaryByLabId.set(p.labResultId, p.patientSummary);
          }
        }
      }

      const safeLabs = labs.map((lab) => {
        const interp = (lab.interpretationResult as any) || {};
        const ov = (lab.providerOverrides as any) || {};
        const hiddenSections: string[] = ov.hiddenSections || [];
        const hiddenInterpCats: string[] = ov.hiddenInterpretationCategories || [];
        const hiddenPhenotypeNames: string[] = ov.hiddenPhenotypeNames || [];
        const hiddenPatternNames: string[] = ov.hiddenPatternNames || [];
        const hiddenHormonePatternCats: string[] = ov.hiddenHormonePatternCategories || [];
        const hiddenSuppNames: string[] = ov.hiddenSupplementNames || [];
        const addedSupplements: any[] = ov.addedSupplements || [];

        const allInterpretations: any[] = interp.interpretations || [];
        // Apply per-row interpretation hiding
        const visibleInterps = allInterpretations.filter(
          (i: any) => !hiddenInterpCats.includes(i.category || '')
        );

        // Build effective supplement list: auto-generated minus hidden, plus provider-added
        const autoSupps: any[] = interp.supplements || [];
        const effectiveSupplements = [
          ...autoSupps.filter((s: any) => !hiddenSuppNames.includes(s.name || '')),
          ...addedSupplements,
        ];

        return {
          id: lab.id,
          labDate: lab.labDate,
          createdAt: lab.createdAt,
          labValues: lab.labValues || null,
          // Filter hormone-pattern rows out — they appear in the hormone assessment section
          // Also gate the entire table if the provider hid the labResults section
          interpretations: hiddenSections.includes('labResults')
            ? []
            : visibleInterps.filter((i: any) => !isHormonePattern(i.category || '')),
          // Surface hormone pattern rows separately; apply section & row-level hiding
          hormonePatternRows: hiddenSections.includes('hormonePatterns')
            ? []
            : visibleInterps
                .filter((i: any) => isHormonePattern(i.category || ''))
                .filter((i: any) => !hiddenHormonePatternCats.includes(i.category || '')),
          supplements: effectiveSupplements,
          // Health Assessment: provider draft > published summary > AI-generated fallback
          patientSummary: (typeof ov.patientSummaryDraft === 'string')
            ? ov.patientSummaryDraft
            : (summaryByLabId.get(lab.id) ?? interp.patientSummary ?? null),
          preventRisk: hiddenSections.includes('preventRisk') ? null : (interp.preventRisk || null),
          insulinResistance: hiddenSections.includes('insulinResistance') ? null : (interp.insulinResistance || null),
          // Female clinical phenotypes: section and item-level hiding
          clinicalPhenotypes: hiddenSections.includes('clinicalPhenotypes')
            ? null
            : ((interp.clinicalPhenotypes as any[] | null)
                ?.filter((p: any) => !hiddenPhenotypeNames.includes(p.name || ''))
              ?? null),
          // Male hormone patterns: section and item-level hiding
          maleHormonePatterns: hiddenSections.includes('maleHormonePatterns')
            ? null
            : ((interp.maleHormonePatterns as any[] | null)
                ?.filter((p: any) => !hiddenPatternNames.includes(p.name || ''))
              ?? null),
          clinicianNotes: notesByLabId.get(lab.id) ?? null,
          // Per-lab dietary guidance from the matching published protocol
          dietaryGuidance: dietaryByLabId.get(lab.id) ?? null,
        };
      });
      res.json(safeLabs);
    } catch (error) {
      console.error("[PORTAL] Error fetching labs:", error);
      res.status(500).json({ message: "Failed to fetch lab history" });
    }
  });

  // ── Clinician: Save provider overrides (visibility + supplement customization) ─
  app.patch("/api/patients/:id/labs/:labId/provider-overrides", requireAuth, async (req, res) => {
    try {
      const clinicianId = getClinicianId(req);
      const clinicId = getEffectiveClinicId(req);
      const patientId = parseInt(req.params.id);
      const labId = parseInt(req.params.labId);
      const overrides = req.body;
      if (!overrides || typeof overrides !== 'object' || Array.isArray(overrides)) {
        return res.status(400).json({ message: "overrides must be an object" });
      }
      const patient = await storage.getPatient(patientId, clinicianId, clinicId);
      if (!patient) return res.status(404).json({ message: "Patient not found" });
      const labResult = await storage.getLabResult(labId);
      if (!labResult || labResult.patientId !== patientId) {
        return res.status(404).json({ message: "Lab result not found" });
      }
      const updated = await storage.updateLabResultProviderOverrides(labId, overrides);
      res.json({ message: "Provider overrides saved", providerOverrides: updated?.providerOverrides ?? null });
    } catch (error) {
      console.error("Error updating provider overrides:", error);
      res.status(500).json({ message: "Failed to update provider overrides" });
    }
  });

  // ── Clinician: Update patient summary for a saved lab result ──────────────
  // This keeps the portal "Your Health Assessment" in sync when provider edits it.
  app.patch("/api/patients/:id/labs/:labId/patient-summary", requireAuth, async (req, res) => {
    try {
      const clinicianId = getClinicianId(req);
      const clinicId = getEffectiveClinicId(req);
      const patientId = parseInt(req.params.id);
      const labId = parseInt(req.params.labId);
      const { patientSummary } = req.body;
      if (typeof patientSummary !== 'string') {
        return res.status(400).json({ message: "patientSummary must be a string" });
      }
      // Verify clinician can access this patient
      const patient = await storage.getPatient(patientId, clinicianId, clinicId);
      if (!patient) return res.status(404).json({ message: "Patient not found" });
      // Fetch the lab result and verify it belongs to this patient
      const labResult = await storage.getLabResult(labId);
      if (!labResult || labResult.patientId !== patientId) {
        return res.status(404).json({ message: "Lab result not found" });
      }
      // Merge updated patientSummary into the stored interpretationResult JSON
      const existing = (labResult.interpretationResult as any) || {};
      const updated = await storage.updateLabResult(labId, {
        interpretationResult: { ...existing, patientSummary } as any,
      });
      res.json({ message: "Patient summary updated", patientSummary });
    } catch (error) {
      console.error("Error updating patient summary:", error);
      res.status(500).json({ message: "Failed to update patient summary" });
    }
  });

  // ── Portal: Get latest published protocol ─────────────────────────────────
  app.get("/api/portal/protocol", requirePortalAuth, async (req, res) => {
    try {
      const patientId = (req.session as any).portalPatientId as number;
      const protocol = await storage.getLatestPublishedProtocol(patientId);
      if (!protocol) return res.json(null);
      // Stamp first viewed timestamp (no-op if already set)
      if (!protocol.firstViewedAt) {
        storage.markProtocolViewed(protocol.id).catch(() => {});
      }
      // Get clinician info
      const clinician = await storage.getUserById(protocol.clinicianId);
      res.json({ ...protocol, clinicName: clinician?.clinicName, clinicianName: clinician ? `${clinician.title} ${clinician.firstName} ${clinician.lastName}` : undefined });
    } catch (error) {
      console.error("[PORTAL] Error fetching protocol:", error);
      res.status(500).json({ message: "Failed to fetch protocol" });
    }
  });

